window.COURSE_DATA={"coveredThrough": 5, "sessions": [{"id": 1, "title": "Ask a question worth answering", "topic": "Orientation, readiness & business-question framing", "module": "M00 / M01", "badge": "Question framer", "summary": "Turn a broad concern into an evidence question, define what each row represents, and make the next decision explicit.", "outcomes": ["Name the stakeholder, decision, population, and time horizon.", "Distinguish the business problem from the software task.", "Check grain, units, provenance, and tool readiness."], "nodes": [["Start with the decision", "Concern → stakeholder → action → evidence", "A business problem describes a condition. A decision names a choice. An analytic question identifies evidence that could inform that choice.", "For a fictional museum café, ask whether next month's weekend staffing should change, then identify which service measure could inform that choice."], ["Define the evidence", "Population → grain → variable → provenance", "Grain states what one row represents. A customer may have several transactions; transaction counts are not customer counts.", "A row for each café visit supports a visit-level wait measure. Line-item rows must be reconciled before counting visits."], ["Set a measure and a guardrail", "Numerator / eligible denominator → unit → target", "A KPI needs an operational definition, reporting period, eligible population, and denominator. A guardrail limits harm or unacceptable data quality.", "Pair a service target with a missing-wait guardrail so a good rate cannot hide poor records."], ["Make reasoning inspectable", "Observation → inference → assumption → next action", "Software calculates. People judge whether evidence supports a recommendation. Keep observed facts separate from claims about causes or the future.", "Report what the available visits show, explain uncertainty, and propose a bounded check before a permanent decision."]], "questions": [["Which is an analytic question?", ["Open SPSS.", "What share of eligible visits exceeded ten minutes last month?", "Service feels slow."], 1, ["That names a software task. First identify the evidence needed.", "Correct. It identifies a measurable outcome, eligible cases, and a period.", "That describes a concern. It still needs an outcome and scope."]], ["One customer makes three visits. At visit grain, how many observations are there?", ["One", "Three", "It depends on the chart."], 1, ["One is the customer count, not the visit count.", "Correct. Grain determines the unit being counted.", "A chart does not change the observational unit."]], ["What makes a recommendation easier to audit?", ["Separate observations, assumptions, and the proposed action.", "Use the most advanced software.", "Remove every limitation."], 0, ["Correct. A visible reasoning path lets another person inspect the decision.", "Complex software cannot replace clear reasoning.", "Limits matter. Removing them makes evidence harder to judge."]]]}, {"id": 2, "title": "Give every measure a contract", "topic": "KPIs, variables, grain & data stories", "module": "M01 / M02", "badge": "Measure designer", "summary": "Choose a valid measure, keep denominators visible, and match the display to the variable and question.", "outcomes": ["Identify nominal, ordinal, interval, and ratio measures.", "Define a KPI's population, unit, denominator, and period.", "Critique chart scale, aggregation, and the implied story."], "nodes": [["Decompose the measure", "Construct → operational variable → values", "A construct such as satisfaction becomes an observed variable through a stated question or measurement process. Coding does not automatically establish equal intervals.", "A single satisfaction item is ordered categorical. Dollar revenue has a meaningful zero and supports ratios."], ["Choose the right unit", "Grain → key → population → period", "Keep one observation at the intended grain. Define eligibility and dates before aggregating. A line-item join can duplicate an order-level outcome.", "An order with three products is still one order for an order-level late-delivery rate."], ["Show the denominator", "Known outcomes → missing outcomes → bounds", "The rate among measured cases answers a different question from the rate among all eligible cases. Unknown outcomes cannot simply be counted as successes.", "Show the observed rate and plausible best/worst bounds when outcomes are missing."], ["Tell a bounded data story", "Question → display → interpretation → action", "Use bars for category comparisons, histograms for numeric distributions, and scatterplots for two numeric variables. Labels, units, source, and scale support honest comparison.", "Start count bars at zero. Joining unordered categories with a line implies an unsupported ordering."]], "questions": [["A single five-category satisfaction item is usually what level?", ["Nominal", "Ordinal", "Ratio"], 1, ["The categories have an order, beyond nominal labels.", "Correct. Order is meaningful; coding 1–5 does not establish equal gaps.", "There is no meaningful absolute zero or justified claim that 4 is twice 2."]], ["A wait outcome is missing. What should you do?", ["Treat it as zero minutes.", "State missingness and denominator, then inspect its cause.", "Exclude it without mentioning it."], 1, ["Zero is a valid measurement, not a missing-value code.", "Correct. The missing mechanism can change KPI interpretation.", "That changes the population summarized and conceals uncertainty."]], ["Which chart shows a numeric wait-time distribution?", ["Histogram", "Pie chart", "A line connecting customer IDs"], 0, ["Correct. Bins summarize counts over numeric ranges.", "A pie compares parts of a whole, not numeric shape.", "Identifiers are labels. A joining line adds an unsupported order."]]]}, {"id": 3, "title": "Read the shape of the evidence", "topic": "Data quality, distributions & descriptive evidence", "module": "M02", "badge": "Distribution detective", "summary": "Audit records, compare center and spread, and explore how unusual observations change a summary.", "outcomes": ["Inspect duplicates, missingness, and unusual values before summarizing.", "Compare mean, median, standard deviation, quartiles, and IQR.", "Choose useful displays and explain descriptive limits."], "nodes": [["Audit before averaging", "Raw rows → distinct cases → valid measurements", "A duplicated key may be a repeated export or a key problem. Investigate it. Missing and unusual observations need separate treatment.", "Keep a raw copy and reconciliation record. Report eligible cases and valid measurements."], ["Compare center", "Mean ↔ median ↔ shape", "The mean uses every magnitude. The median uses order and position. A long right tail can pull the mean above the median.", "Five delivery times can retain the same median while one long delivery substantially increases the mean."], ["Describe spread", "SD ↔ range ↔ quartiles ↔ IQR", "Standard deviation summarizes variation around the mean. IQR is Q3 minus Q1. An outlier fence is a review flag, not proof of error.", "Check a flagged value against its source. Preserve valid unusual observations and report sensitivity if it matters."], ["Choose the display", "Distribution → comparison → relationship", "A dot plot shows each small-sample observation. A histogram depends on bins. Box plots compactly compare distributions but do not show every shape feature.", "Show group sizes and missingness. A descriptive difference alone does not establish causation."]], "questions": [["One valid delivery time rises from 26 to 80 minutes. Which changes more?", ["The median", "The mean", "Neither changes"], 1, ["The middle sorted value stays 22 minutes.", "Correct. The mean uses the changed magnitude; the middle value remains 22.", "The sum increases, so the mean increases."]], ["An observation lies beyond an IQR fence. What does that establish?", ["It is a data error.", "It should be investigated.", "It must be replaced by the mean."], 1, ["An unusual value may be real. A flag is not proof of error.", "Correct. Check provenance and plausibility, then explain any treatment.", "Replacement requires a defensible reason, beyond a flag."]], ["Group A has a larger average than Group B in an extract. Can you infer causation?", ["Yes, the average proves it.", "Only if the bars are separated.", "No. Design, selection, and other differences still matter."], 2, ["An average is descriptive. Study design governs causal interpretation.", "Visual separation does not resolve confounding or selection.", "Correct. State the observed difference and design limits."]]]}, {"id": 4, "title": "Make decisions under uncertainty", "topic": "Conditional risk, expected value & simulation", "module": "M03", "badge": "Risk navigator", "summary": "Distinguish joint from conditional probability, compare payoffs across states, and inspect risk alongside averages.", "outcomes": ["Calculate conditional probability with the correct reference group.", "Compare actions using expected value and downside.", "Use simulation as a model-based experiment and test assumptions."], "nodes": [["Name the reference group", "Event A and B → P(A | B)", "Conditional probability restricts the denominator to the condition. P(A | B) need not equal P(B | A). Base rates matter.", "A screen can detect most true cases while many positive screens are false alarms when the event is rare."], ["Choose across uncertain states", "States → probabilities → payoffs → expected value", "Expected value weights outcomes by probability. Probabilities sum to one, and payoffs use compatible units and horizons.", "Higher expected profit may come with a larger adverse-state loss. Compare both."], ["Model and simulate", "Inputs → trial logic → outputs → sensitivity", "Simulation explores assumptions. Its output is an estimate, not population truth. Inspect reproducibility and trial counts.", "Separate an analytic expectation from a particular run's mean. Check units, boundary inputs, and downside."], ["Communicate bounded risk", "Expected result + downside + reversal condition", "Explain which assumption could reverse the action. A fifth percentile is a cut-off with roughly 5% below it, not a guaranteed minimum.", "Name the threshold, loss risk, and next evidence before committing resources."]], "questions": [["For P(event | positive screen), what is the denominator?", ["All true events", "All positive screens", "The entire population"], 1, ["That denominator belongs to sensitivity, P(positive | event).", "Correct. Conditioning on a positive screen restricts the reference group.", "The whole population is used for a joint proportion, not this conditional probability."]], ["Does higher expected profit guarantee higher profit next time?", ["Yes", "No", "Only with a large chart"], 1, ["Expected value averages across states. One realized state can be worse.", "Correct. Check downside, assumptions, and decision horizon as well.", "Display size does not change uncertainty."]], ["What does the fifth percentile of profit mean?", ["A guaranteed profit floor", "About 5% of modeled outcomes fall below that cut-off", "The average profit"], 1, ["Some outcomes are worse. It is not a floor.", "Correct. Describe the model and horizon as well as the percentile.", "A percentile describes position, not the mean."]]]}, {"id": 5, "title": "Put uncertainty around the estimate", "topic": "Sampling, bias, confidence intervals & precision", "module": "M04", "badge": "Uncertainty interpreter", "summary": "Separate individual variability from estimate variability, audit sampling, and interpret confidence correctly.", "outcomes": ["Distinguish population, frame, sample, parameter, and statistic.", "Explain standard error and the square-root rule.", "Interpret confidence and precision while checking bias and independence."], "nodes": [["Audit the sample", "Population → frame → draw → response", "A probability draw does not ensure unbiased responses. Coverage, nonresponse, and clustering can weaken generalization.", "Record who was eligible, reachable, selected, and observed. More responses from the same selection mechanism may preserve bias."], ["Separate two variations", "Individual SD → sampling distribution → SE", "SD describes observations. Standard error describes estimator variability across repeated samples. For an independent mean, SE is approximately s / √n.", "Quadrupling n approximately halves SE when design and population variation remain comparable."], ["Build and read an interval", "Estimate ± critical value × SE", "For a mean with unknown population SD, use the appropriate Student t critical value under the procedure's conditions. A 95% method has approximately 95% long-run coverage.", "It does not contain 95% of individual customers. A calculated fixed interval either covers the fixed population mean or it does not."], ["Plan useful precision", "Margin of error → sample-size plan → bias check", "Precision depends on confidence, variability, sample size, and design. Narrow intervals can still miss the target in a biased sample.", "Specify an actionable margin of error, round sample-size requirements upward, and check the sampling frame."]], "questions": [["What does a 95% confidence procedure describe?", ["95% of individual outcomes lie in each interval.", "About 95% of repeated comparable intervals cover the fixed parameter.", "There is always a 95% chance the sample mean is correct."], 1, ["That concerns individual outcomes, not uncertainty around a population estimate.", "Correct. Confidence describes long-run coverage under the assumptions.", "The sample mean is an estimate. Coverage concerns the population parameter and procedure."]], ["If n rises from 25 to 100 under the same independent design, what happens to SE?", ["It roughly halves.", "It doubles.", "It remains unchanged."], 0, ["Correct. √100 is twice √25, so the denominator doubles.", "More independent observations reduce estimate variability here.", "SD may remain similar, but standard error decreases."]], ["Can a much larger convenience sample automatically repair selection bias?", ["Yes", "No", "Only at 99% confidence"], 1, ["The selection mechanism remains. A precise estimate can still be biased.", "Correct. Fix sampling and investigate coverage and nonresponse.", "Higher confidence changes width, not selection."]]]}], "future": [[6, "Hypothesis tests, effect size & A/B decisions"], [7, "Midterm Decision Analysis"], [8, "Group comparisons & test selection"], [9, "Correlation, categorical relationships & confounding"], [10, "Regression & conditional interpretation"], [11, "Diagnostics, forecasting & fairness"], [12, "Project revision & reproducibility"], [13, "Executive communication & rehearsal"], [14, "Final showcase & oral defense"]]};